(() => {
 const data=window.SCHOOL_DATA,main=document.getElementById('main'),params=new URLSearchParams(location.search),all=data.lessons||[];
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const url=l=>'lessons.html?lesson='+encodeURIComponent(l.id),read=l=>'reader.html?lesson='+encodeURIComponent(l.id)
const media=window.SCHOOL_MEDIA||{lessons:{},topics:{}},mediaBlock=(list,title,note)=>list&&list.length?`<section class="media-links"><h2>${esc(title)}</h2>${note?`<p>${esc(note)}</p>`:''}<ul>${list.map(m=>`<li><a href="${esc(m.url)}" target="_blank" rel="noopener"><span class="media-kind media-${m.type}">${m.type==='padlet'?'Padlet':'影片'}</span><span class="media-label">${esc(m.label)}</span>${m.star?'<span class="media-star">推薦</span>':''}<span class="media-go" aria-hidden="true">↗</span></a></li>`).join('')}</ul></section>`:'';
 const cover=(l,thumb=false)=>l.cover?data.assets[l.cover][thumb?'thumb':'src']:l.coverPage;
 const term=l=>`${l.year}${l.semester===1?'上':'下'}`;
 const heading=(title,description,detail=false)=>`<header class="page-heading"><div class="breadcrumb"><a href="index.html">首頁</a><span>/</span>${detail?'<a href="lessons.html">教案書屋</a><span>/</span>':''}<span>${esc(title)}</span></div><h1>${esc(title)}</h1><p>${esc(description)}</p></header>`;
 const card=l=>`<article class="resource-card visual-card lesson-card"><a class="card-image ${l.cover?'':'image-contain'}" href="${url(l)}" tabindex="-1" aria-hidden="true"><img src="${esc(cover(l,true))}" alt="" loading="lazy"></a><div class="card-copy"><span class="type-label">${esc(l.topic)}</span><h3><a href="${url(l)}">${esc(l.title)}</a></h3><div class="meta-line"><span>${term(l)}</span><span>${esc(l.course)}</span></div><p>${esc(l.summary)}</p><div class="card-bottom"><a class="text-link" href="${url(l)}">打開這份教案 →</a><span>${l.end-l.start+1} 頁${l.periods?' · '+l.periods+' 節':''}</span></div></div></article>`;
 document.querySelector('a[href="lessons.html"]')?.setAttribute('aria-current','page');
 const selected=all.find(l=>l.id===params.get('lesson'));
 if(params.has('lesson')){
  if(!selected){main.innerHTML=heading('換一堂課，繼續探索','回到教案書屋，挑選一個主題開始。')+'<a class="button" href="lessons.html">返回教案書屋</a>';return;}
  const l=selected;document.title=l.title+'｜Salimpo 教案書屋';
  main.innerHTML=heading(l.title,l.summary,true)+`<article class="page-body rich-story lesson-detail"><div class="story-hero ${l.cover?'':'image-contain'}"><img src="${esc(cover(l))}" alt="${esc(l.title)}的圖文內容"></div><div class="story-facts"><span>${esc(l.band)}</span><span>${term(l)}</span><span>${esc(l.course)}</span><span>${esc(l.topic)}</span>${l.periods?'<span>'+l.periods+' 節</span>':''}<span>${l.end-l.start+1} 頁教案</span></div><div class="story-layout"><div><section class="story-chapter"><p class="chapter-number">01 / LET'S LEARN</p><h2>這堂課，從這裡開始</h2><p>${esc(l.summary)}</p></section>${l.objectives?`<section class="story-chapter"><p class="chapter-number">02 / LEARNING GOALS</p><h2>這堂課想學會什麼？</h2><p class="lesson-excerpt">${esc(l.objectives)}</p></section>`:''}${l.vocabulary?`<section class="story-chapter"><p class="chapter-number">03 / WORDS IN OUR LIFE</p><h2>教案裡的族語與關鍵詞</h2><p class="lesson-excerpt">${esc(l.vocabulary)}</p></section>`:''}${mediaBlock(media.lessons[l.id],'看原板與影片','點了會開新分頁，看 Padlet 學習歷程原板和課程影片。')}</div><aside class="story-reading"><p class="eyebrow">OPEN THIS LESSON</p><h2>走進這個主題</h2><a class="reading-entry" href="${read(l)}"><span>完整教學內容</span><strong>閱讀${esc(l.title)}教案</strong><small>${l.end-l.start+1} 頁 · 主題內搜尋 ↗</small></a>${l.resource?`<a class="reading-entry" href="resource.html?id=${esc(l.resource)}"><strong>看看課程照片與成果</strong><small>延伸探索 ↗</small></a>`:''}${(data.journeys||[]).filter(j=>j.lessons.includes(l.id)).map(j=>`<a class="reading-entry" href="journeys.html#${esc(j.id)}"><span>我們怎麼學</span><strong>${esc(j.title)}</strong><small>${[j.term,j.band].filter(Boolean).map(esc).join(' · ')} · ${j.steps.length} 個步驟 ↗</small></a>`).join('')}<a class="text-link" href="lessons.html">← 回教案書屋</a></aside></div><section class="lesson-pages"><div class="album-heading"><div><p class="eyebrow">A LOOK INSIDE</p><h2>翻開教案看看</h2></div><a class="text-link" href="${read(l)}">閱讀全部 ${l.end-l.start+1} 頁 →</a></div><div class="lesson-page-preview">${[l.start,Math.min(l.end,l.start+1)].map(n=>`<a href="reader.html?lesson=${esc(l.id)}&page=${n}" aria-label="閱讀${esc(l.title)}教案第${n-l.start+1}頁"><img src="media/${esc(l.book)}/${String(n).padStart(3,'0')}.webp" alt="${esc(l.title)}教案第${n-l.start+1}頁" loading="lazy"></a>`).join('')}</div></section><section class="story-related"><h2>同一個主題，還有這些課</h2><div class="resource-grid">${all.filter(x=>x.id!==l.id&&x.topic===l.topic).slice(0,3).map(card).join('')}</div></section></article>`;return;
 }
 document.title='按主題找教案｜Salimpo 教案書屋';
 main.innerHTML=heading('挑一個主題，走進一堂課','山林、海洋、歌謠、工藝和部落故事，找找下一堂課的靈感。')+`<div class="page-body"><nav class="lesson-topics" aria-label="教案主題"><button type="button" data-topic="" aria-pressed="true">全部主題</button>${data.lessonTopics.map(t=>`<button type="button" data-topic="${esc(t)}" aria-pressed="false">${esc(t)}</button>`).join('')}</nav><form class="filters lesson-filters" role="search" aria-label="搜尋教案"><label class="filter-field" for="lesson-query">找一堂課<input id="lesson-query" type="search" placeholder="例如：野番茄、家屋、族語"></label><label class="filter-field" for="lesson-band">年段<select id="lesson-band"><option value="">全部年段</option>${['低年級','中年級','高年級'].map(b=>`<option>${b}</option>`).join('')}</select></label><label class="filter-field" for="lesson-term">學期<select id="lesson-term"><option value="">全部學期</option><option value="1">114上學期</option><option value="2">114下學期</option></select></label></form><div class="results-top"><p id="lesson-count" class="results-count" role="status" aria-live="polite"></p><button type="button" class="reset-button" id="lesson-reset">重新探索</button></div><div id="lesson-results"></div><div id="lesson-media"></div><section class="lesson-more-books"><h2>教案旁邊的更多靈感</h2><div class="related-list"><a href="reader.html?book=report114a&page=555"><span>上學期評量規準與學習單</span><span>閱讀內容 ↗</span></a><a href="reader.html?book=assessment"><span>學習成果評量單</span><span>打開表件 ↗</span></a><a href="reader.html?book=report114b"><span>山海學習全紀錄</span><span>完整成果 ↗</span></a></div></section></div>`;
 let topic=params.get('topic')||'',query=document.getElementById('lesson-query'),band=document.getElementById('lesson-band'),semester=document.getElementById('lesson-term');query.value=params.get('q')||'';band.value=params.get('band')||'';semester.value=params.get('semester')||'';
 function draw(){const q=query.value.trim().toLocaleLowerCase(),list=all.filter(l=>(!topic||l.topic===topic)&&(!band.value||l.band===band.value)&&(!semester.value||String(l.semester)===semester.value)&&(!q||[l.title,l.summary,l.topic,l.course,l.vocabulary,l.objectives].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>b.semester-a.semester||a.start-b.start);document.getElementById('lesson-count').textContent=`找到 ${list.length} 組教案 · 共 ${all.length} 個主題單元`;document.getElementById('lesson-results').innerHTML=list.length?['低年級','中年級','高年級'].map(b=>{const rows=list.filter(l=>l.band===b);return rows.length?`<section class="lesson-band-group"><div class="album-heading"><h2>${b}的學習旅程</h2><p>${rows.length} 組教案</p></div><div class="resource-grid">${rows.map(card).join('')}</div></section>`:'';}).join(''):'<div class="empty-state"><h2>換個主題，再找找看</h2><p>試試其他關鍵字或年段。</p></div>';document.getElementById('lesson-media').innerHTML=topic?mediaBlock(media.topics[topic],topic+'：更多 Padlet 原板與影片','其他學年度的學習歷程和影片，點了會開新分頁。'):''
main.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===topic)));const u=new URL(location.href);u.search='';for(const [k,v] of [['topic',topic],['q',query.value],['band',band.value],['semester',semester.value]])if(v)u.searchParams.set(k,v);history.replaceState(null,'',u);}
 main.querySelector('form').onsubmit=e=>{e.preventDefault();draw();};query.oninput=draw;band.onchange=draw;semester.onchange=draw;main.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{topic=b.dataset.topic;draw();});document.getElementById('lesson-reset').onclick=()=>{topic='';query.value='';band.value='';semester.value='';draw();};draw();
})();
